// Writes out/.htaccess for Apache (Bluehost) from redirects.mjs.
import { writeFileSync } from "node:fs";
import { siteRedirects } from "../redirects.mjs";

const lines = [
  "# Generated by scripts/write-htaccess.mjs. Do not edit by hand.",
  "Options -Indexes",
  "ErrorDocument 404 /404.html",
  // Next.js writes these generated images without file extensions.
  '<FilesMatch "^opengraph-image$">',
  "  ForceType image/jpeg",
  "</FilesMatch>",
  '<FilesMatch "^apple-icon$">',
  "  ForceType image/png",
  "</FilesMatch>",
  "RewriteEngine On",
  // One hop to https://www., the canonical host in src/content/site.ts.
  "RewriteCond %{HTTPS} off [OR]",
  "RewriteCond %{HTTP_HOST} !^www\\. [NC]",
  "RewriteRule ^ https://www.abimbolaolumuyiwa.com%{REQUEST_URI} [L,R=301]",
  ...siteRedirects.map((r) => {
    const from = r.source.replace(/^\//, "").replace(/:slug$/, "([^/]+)");
    const to = r.destination.replace(":slug", "$1");
    return `RewriteRule ^${from}/?$ ${to}/ [L,R=301]`;
  }),
];
writeFileSync("out/.htaccess", lines.join("\n") + "\n");
console.log(`out/.htaccess: ${siteRedirects.length} redirects`);
